mapper.sql:

EXISTS (
    SELECT 1 FROM contest_problem cp
    JOIN contest c ON c.id = cp.contest_id
    WHERE cp.problem_id = p.id AND c.source_id = #{originalSourceId} AND c.end_time > #{now}
)



CASE
    WHEN  THEN #{contestVisibility}
    WHEN p.visibility = #{contestVisibility} THEN #{privateVisibility}
    ELSE p.visibility
END

mapper.select:

SELECT EXISTS (
    SELECT 1 FROM contest_problem cp
    JOIN contest c ON c.id = cp.contest_id
    WHERE cp.problem_id = #{problemId} AND c.source_id = #{originalSourceId} AND c.end_time > #{now}
)

SELECT p.id, p.problem_id, p.title, p.content, p.time_limit, p.memory_limit, p.`input`, p.`output`, p.examples, p.source, p.difficulty, p.judge_mode, AS visibility, p.open_case_result, p.author_id, p.author_username, p.created_time, p.updated_time FROM problem p
AND p.author_id = #{scope.userId}
AND (p.title LIKE CONCAT('%', #{query.keyword}, '%') OR p.problem_id LIKE CONCAT('%', #{query.keyword}, '%'))
AND p.difficulty = #{query.difficulty}
AND = #{query.visibility}
ORDER BY p.created_time DESC, p.id DESC
